  it("adds two positive numbers", () => {
    expect(add(2, 3)).toBe(5);
  });

  it("adds negative numbers", () => {
    expect(add(-2, -3)).toBe(-5);
    expect(add(-2, 3)).toBe(1);
  });

  it("treats zero as the identity", () => {
    expect(add(0, 7)).toBe(7);
    expect(add(7, 0)).toBe(7);
